export const PAINTS=[{id:'stock',name:'Factory'},{id:'champion',name:'Champion Gold',color:'#e7bc50',unlock:'champion'},{id:'ember',name:'Ember',color:'#ff804d',unlock:'drifter'},{id:'cyan',name:'Glacier',color:'#43d8ee'},{id:'red',name:'Signal',color:'#ed4b62'},{id:'purple',name:'Ultraviolet',color:'#a576f6'},{id:'lime',name:'Acid',color:'#b9e754'},{id:'white',name:'Pearl',color:'#e6eef0'},{id:'blue',name:'Electric',color:'#3984f5'},{id:'black',name:'Graphite',color:'#35414e'}];
export const FINISHES=[{id:'gloss',name:'Gloss'},{id:'matte',name:'Matte'}];
export const STRIPES=[{id:'none',name:'None'},{id:'light',name:'Ice',color:'#eef8ff'},{id:'dark',name:'Onyx',color:'#17202d'},{id:'neon',name:'Neon',color:'#c8fa62'}];
export const SPOILERS=[{id:'stock',name:'Factory'},{id:'none',name:'Clean'},{id:'wing',name:'Wing'}];
export const GLOWS=[{id:'none',name:'Off'},{id:'cyan',name:'Cyan',color:'#42edff'},{id:'pink',name:'Pink',color:'#ff50d5'},{id:'lime',name:'Lime',color:'#bdff63'}];
export function normalizeAppearance(raw){return Object.fromEntries(Object.entries({paint:PAINTS,finish:FINISHES,stripe:STRIPES,spoiler:SPOILERS,glow:GLOWS}).map(([key,list])=>[key,list.some(o=>o.id===raw?.[key])?raw[key]:list[0].id]));}
export function appearanceFor(profile,car=profile.car){const look=normalizeAppearance(profile.customization?.[car]);const required=PAINTS.find(p=>p.id===look.paint)?.unlock;if(required&&!profile.cosmeticUnlocks?.includes(required))look.paint='stock';return look;}
export function saveAppearance(profile,car,appearance){if(!profile.ownedCars.includes(car)||PAINTS.find(p=>p.id===appearance?.paint)?.unlock&&!profile.cosmeticUnlocks?.includes(PAINTS.find(p=>p.id===appearance?.paint).unlock))return false;profile.customization??={};profile.customization[car]=normalizeAppearance(appearance);return true;}
export function paintColor(spec,appearance){return PAINTS.find(p=>p.id===normalizeAppearance(appearance).paint)?.color||spec.color;}
